window.__BUNDLE__={"generatedAt":"2026-11-21T11:42:26.910427+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-11-14","archiveCutoff":"2021-11-22","addedToday":0,"addedThisRun":0,"fetchStats":{"hf":254,"arxiv":1349,"total":1603},"freshness":{"latestPaperDate":"2026-11-20","latestPublishedDate":"2026-11-20","latestBatchCount":307,"newInLast24h":257,"newInLast48h":625},"historyTotal":34544,"topicCounts":{"Multi-Agent":3468,"Evaluation":19036,"Planning":2483,"Memory":663,"Code Agent":1412,"Interpretability":1152,"Agentic RAG":1673,"Agentic Search":2266,"RL for LLM":1729,"Reasoning":8985,"Hallucination":1430,"Post-Training":3668,"Alignment":4451,"World Model":700,"Tool Use":1550,"Agent Safety":2909,"Computer Use":432,"Reflection":1251,"VLM Training":2860,"LLM Training":4426,"Fine-tuning":5348,"Multimodal Agent":209,"Agent Framework":1046,"Error Attribution":212,"Data Engine":694},"count":36,"recentTotal":1896,"archiveCount":0,"archiveTotal":32648,"sources":{"hf":55,"arxiv":1841,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"tags":["Reasoning","Evaluation","Multimodal Agent"],"title":"Mind2Act World: A Diagnostic Benchmark for Embodied Mind, Physical Action, and Mind-Action Composition in Robotic Manipulation","pdf":"https://arxiv.org/pdf/2611.26444.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.26444","id":"arxiv:2611.26444","source":"hf","upvotes":46,"url":"https://arxiv.org/abs/2611.26444","topics":["Reasoning","Evaluation","Multimodal Agent"],"authors":["Yuzhi Huang","Jie Wu","Fanding Huang","Junchao Lin","Weichen Zhang","Ziyi Xiong","Yang Li","Zhengwei Xie","Zhimin Wang","Zhen Liu","Jiazhen Huang","Yuzheng Zhang","Yuche Liu","Hongyi Yang","Chen Tang","Shixiang Tang","Hakan Aktas","Adam Wu","Duo Wu","Kangye Ji","Shuzhao Xie","Huanan Liu","Weijue Bu","Chenxin Li","Xinyuan Wang","Tianyi Bai","Yinan Mao","Jiawei Wang","Minglei Li","Heng Yu","Ehsan Adeli","Minchen Li","Yong-Lu Li","Cengiz Öztireli","Huazhe Xu","Chao Yu","Jing Zhang","Shanghang Zhang","Weitao Zhou","Wenwu Zhu","Cheng Chi","Jingyan Jiang","Zhi Wang"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.26444","announceDate":"2026-11-20","abstract":"Embodied intelligence aims to let robots perform complex physical tasks with human-like adaptability and reliability, which requires three complementary capabilities: history-based cognitive reasoning, precise and timely physical execution, and the composition of reasoning and execution through environmental feedback. Yet existing benchmarks either evaluate reasoning and execution within the same tasks or assess them separately without their composition, so they reveal little about whether a failure comes from reasoning, execution, or their composition. We introduce Mind2Act World, a diagnostic benchmark of 30 simulated manipulation tasks from five real-world application domains. Each task has three difficulty levels and two scene settings (Clean and Random), yielding 180 configurations. The tasks form three views: Mind tests decisions based on past observations, Act tests precise and ti"},{"tags":["VLM Training","Reasoning","Alignment"],"title":"Probing the \"Conscious\" Mind: Selective Access and Global Workspace in Vision-Language Models","pdf":"https://arxiv.org/pdf/2611.26590.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.26590","id":"arxiv:2611.26590","source":"hf","upvotes":41,"url":"https://arxiv.org/abs/2611.26590","topics":["VLM Training","Reasoning","Alignment"],"authors":["Jiahao Huang","Jun Wang"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.26590","announceDate":"2026-11-20","abstract":"Vision-language models (VLMs) integrate visual and textual information, but their outputs do not reveal internal concept representations. Global workspace theory (GWT) proposes that information is selected from parallel brain processes, integrated in a shared workspace, and made available to specialised processes. We introduce the Multimodal Concept Lens (MC-Lens), a multimodal Jacobian lens, to study these functions in VLM concept processing. Its vision encoder and language decoder lenses map intermediate states to a shared semantic space defined by the decoder's output vocabulary to compare concept accessibility across modalities. MC-Lens supports internal concept interventions to examine the role of accessed concepts in downstream computation. (i) Accessibility and selective access. Multimodal concept information is readable in intermediate states and selectively accessible as tasks r"},{"tags":["Post-Training","LLM Training","Reasoning","Evaluation"],"title":"WeMM-Video: Pushing the Frontiers of Open-Source Omni-Modal Video Understanding","pdf":"https://arxiv.org/pdf/2611.26409.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.26409","id":"arxiv:2611.26409","source":"hf","upvotes":40,"url":"https://arxiv.org/abs/2611.26409","topics":["Post-Training","LLM Training","Reasoning","Evaluation"],"authors":["Changli Tang","Jie Yang","Tianyi Wang","Lei Li","Daoze Zhang","Zijie Xin","Zhan Liu","Li Li","Jinchang Xu","Fengyun Rao","Chao Zhang","Jing Lyu"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.26409","announceDate":"2026-11-20","abstract":"Video understanding, particularly with accompanying audio, remains a central challenge in multimodal intelligence. In this report, we introduce \\textbf{WeMM-Video}, a family of Chinese-English bilingual omni-modal foundation models spanning 2B, 4B, 9B, and 35B-A3B variants. Centering on joint audio-visual perception and reasoning, WeMM-Video unifies text, image, audio, and video processing within a hybrid-thinking paradigm, seamlessly supporting both a non-thinking instruct mode for fast, direct responses and a thinking mode for explicit step-by-step reasoning. The models are trained on a large-scale multimodal corpus of approximately 1.2 trillion tokens through progressive pre-training and a multi-stage post-training pipeline incorporating multi-teacher OPD, anti-repetition MrDPO, and specialist RL. Evaluated across more than 120 benchmarks, WeMM-Video demonstrates superior performance "},{"tags":["Evaluation","Alignment"],"title":"Posterior Matching Distillation","pdf":"https://arxiv.org/pdf/2611.26629.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.26629","id":"arxiv:2611.26629","source":"hf","upvotes":35,"url":"https://arxiv.org/abs/2611.26629","topics":["Evaluation","Alignment"],"authors":["Hidir Yesiltepe","Julius Berner","Arash Vahdat","Pinar Yanardag"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.26629","announceDate":"2026-11-20","abstract":"Diffusion distillation accelerates image and video generation by compressing a pretrained teacher's iterative sampling process into a few network evaluations. Distribution-based methods achieve this by matching the student's output distribution to the teacher's. This matching is often driven by reverse-KL objectives, whose mode-seeking bias favors dominant teacher modes at the expense of diversity across samples. We introduce Posterior Matching Distillation (PMD), a new member of the distribution-based distillation family that combines mode-covering posterior sampling with any-step generation. At zero population loss, PMD recovers the teacher's full posterior of clean images at each trained noise level. Its stochastic student supports any-step sampling budgets within the trained timestep grid without further training. To learn these posteriors, PMD matches exponentially reweighted averag"},{"tags":["Multi-Agent","Evaluation"],"title":"Coda-DaVinci: Reimagining Video Generation with Code2Video","pdf":"https://arxiv.org/pdf/2611.26595.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.26595","id":"arxiv:2611.26595","source":"hf","upvotes":34,"url":"https://arxiv.org/abs/2611.26595","topics":["Multi-Agent","Evaluation"],"authors":["Yiyan Ji","Qixun Wang","Yang Shi","Zhuoran Zhang","Yifan Xu","Tengfei Liu","Yuqi Tang","Xiaohan Zhang","Shujie Li","Jiafu Tang","Xuanyu Zhu","Xinyu Liu","Yan He","Yushuo Guan","Zihao Wang","Xianghua Ying","Shixuan Liu","Haotian Wang","Wenjing Yang","Zhaoxiang Zhang","Yuanxing Zhang","Pengfei Wan","Jiaheng Liu"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.26595","announceDate":"2026-11-20","abstract":"Code2Video uses agent-authored 3D proxies to guide video generation, enabling explicit control over structure and dynamics. However, how to construct proxies and prompts for optimal downstream quality remains underexplored, as do the capabilities and limitations of this paradigm. Through controlled experiments and blinded human evaluation, we study proxy granularity, physics simulation, and prompting. The results reveal task-dependent trade-offs: coarse proxies favor natural motion, while medium-grained proxies favor consistency. Physics simulation and proxy-aligned prompting further improve average quality. Guided by these findings, we introduce Coda-DaVinci, a task-adaptive agentic framework for Code2Video generation that selects between proxy-guided and direct generation, adapts modeling granularity to each entity, and coordinates simulation with proxy-grounded prompting. Its multi-ag"},{"tags":["Post-Training","Evaluation","Alignment"],"title":"EgoCaptioner: Towards Comprehensive and Fine-Grained Egocentric Video Captioning","pdf":"https://arxiv.org/pdf/2611.26380.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.26380","id":"arxiv:2611.26380","source":"hf","upvotes":24,"url":"https://arxiv.org/abs/2611.26380","topics":["Post-Training","Evaluation","Alignment"],"authors":["Yuqi Tang","Yang Shi","Yuran Wang","Tengfei Liu","Rundong Wang","Zongyang Qiu","Qixun Wang","Zhuoran Zhang","Xuanyu Zhu","Yifan Xu","Yiyan Ji","Shujie Li","Shixuan Liu","Haotian Wang","Yuanxing Zhang","Pengfei Wan","Chengwei Qin"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.26380","announceDate":"2026-11-20","abstract":"Egocentric video captioning requires fine-grained detail and accurate timing, yet current multimodal large language models (MLLMs) often miss brief actions, confuse their order, or misinterpret the wearer's motion. Existing caption formats also offer limited support for combining detailed narration with precise timing. We present EgoCaptioner, which pairs a video-level overview of the setting, participants, and the wearer's overall activity with timed steps whose narration adapts to varying perceptual demands and marks key moments at specific timestamps. We develop a coarse-to-fine annotation pipeline that establishes event structure before expanding step descriptions, yielding 50,000 training examples from eight egocentric video sources. Complementary rewards assess factual accuracy and coverage, measure step-level temporal alignment, and penalize fragmented or redundant narration, guid"},{"tags":["VLM Training"],"title":"HiUni: Harmonizing Understanding and Generation in Shared Visual Space","pdf":"https://arxiv.org/pdf/2611.26107.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.26107","id":"arxiv:2611.26107","source":"hf","upvotes":23,"url":"https://arxiv.org/abs/2611.26107","topics":["VLM Training"],"authors":["Jiahao Hu","Jingdong Du","Yichen Zhang","Yi Song","Zhenyu Zhang","Jiaxin Niu","Ruihang Li","Xiangzhao Hao","Yiqian Zhang","Yong Huang","Zefeng Zhang","Zheyuan Gu","Shuohuan Wang"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.26107","announceDate":"2026-11-20","abstract":"Unified multimodal models aim to support visual understanding and generation within a single framework. However, prevailing approaches often separate their visual representations or backbone computation to accommodate the different requirements of these two tasks, which limits the degree of unification. In this paper, we present HiUni, which revisits this design choice and explores whether a pretrained vision language model can be directly extended into a unified model with extensive parameter sharing. Specifically, HiUni reuses the same language-aligned ViT and dense Transformer backbone for both capabilities, while confining task-specific computation to the output side. Yet such a design introduces two key challenges. Generation in pixel space is difficult to optimize, and semantic abstraction in pretrained ViT discards fine spatial details required for synthesis. To address these chal"},{"tags":["LLM Training","VLM Training","Evaluation","Fine-tuning"],"title":"ZeroVLN: Learning to Navigate without Supervised Fine-Tuning of the VLM Brain","pdf":"https://arxiv.org/pdf/2611.26414.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.26414","id":"arxiv:2611.26414","source":"hf","upvotes":21,"url":"https://arxiv.org/abs/2611.26414","topics":["LLM Training","VLM Training","Evaluation","Fine-tuning"],"authors":["Zixuan Huang","Yang Zhou","Guli Zhang","Sunzhu Li","Hongyan Xie","Zehao Chen","Fuzhen Zhuang","Kaixuan Wang","Xiaozhi Chen","Yikun Ban","Deqing Wang"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.26414","announceDate":"2026-11-20","abstract":"Representative vision-language navigation (VLN) methods typically couple a vision-language model (VLM) brain with a learnable action head and fine-tune the VLM brain on navigation-domain data to predict geometric goals. However, such adaptation can substantially alter base VLM weights and degrade general visual capabilities. We introduce ZeroVLN, a slow-fast navigation framework that achieves effective navigation with zero navigation-domain SFT of the VLM brain. Rather than teaching the brain to predict geometric goals, we equip it with a semantic tool-calling interface for conveying movement decisions to an action expert in natural language. We first adapt the action expert to carry out these movement requests, then jointly improve the brain's movement decisions and the action expert's continuous execution through closed-loop reinforcement learning (RL). Trained on the same navigation e"},{"tags":["Post-Training","LLM Training","Evaluation","Fine-tuning"],"title":"AutoMaster: Autonomous Post-Training by Making the Same Model a Better Teacher","pdf":"https://arxiv.org/pdf/2611.26510.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.26510","id":"arxiv:2611.26510","source":"hf","upvotes":14,"url":"https://arxiv.org/abs/2611.26510","topics":["Post-Training","LLM Training","Evaluation","Fine-tuning"],"authors":["Guoxin Chen","Shuang Sun","Fanzhe Meng","Xinyu Tang","Ruihua Song","Wayne Xin Zhao"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.26510","announceDate":"2026-11-20","abstract":"Task success alone does not specify which behaviors post-training should reinforce. Even successful teacher trajectories can contain unsupported assumptions, unproductive repetition, or superficial verification. We propose Skill-FT (Skill-Guided Fine-Tuning), which uses natural-language skills to suppress undesirable habits and elicit underrepresented effective behaviors during teacher rollouts, then fine-tunes a target model on the resulting trajectories. We introduce AutoMaster, an autonomous post-training system in which an LLM agent develops these interventions through trajectory analysis, skill design, data selection, and feedback from rollouts and target-model evaluation. Across Terminal, Search, and software engineering tasks with 4B and 9B target models, AutoMaster improves mean performance over Vanilla SFT on successful unguided teacher trajectories by 1.42-8.99 percentage point"},{"tags":["Evaluation"],"title":"Training Vision Models for LLM-Driven Weight-Space Programming","pdf":"https://arxiv.org/pdf/2611.26408.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.26408","id":"arxiv:2611.26408","source":"hf","upvotes":14,"url":"https://arxiv.org/abs/2611.26408","topics":["Evaluation"],"authors":["Timo Ropinski","Sebastian Kranz"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.26408","announceDate":"2026-11-20","abstract":"It has been demonstrated that, in certain settings, large language models can perform weight-space programming to directly modify the weights of neural networks. However, it is unknown how dedicated training of these networks can contribute to the successes of weight-space programming. We present a benchmark of LLM-driven weight-space programming on vision models, in which five LLMs edit convolutional networks and vision transformers on relabeling and error-correction tasks on Waterbirds, CIFAR-100, PACS and Entity-30. We report more than 2,600 such edit processes, whereby each edit is scored on held-out images for success, side effects and accuracy loss. We compare standard training with label smoothing, gradient-based editable training, and our Edit-Ready Training (ERT), a novel method that rehearses the direct, closed-form weight edits LLMs perform. We show that preparing networks for"},{"tags":["Evaluation"],"title":"TwinLab-Bench: Evaluating AI Scientists in Agentic Twins of Real Labs","pdf":"https://arxiv.org/pdf/2611.26248.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.26248","id":"arxiv:2611.26248","source":"hf","upvotes":5,"url":"https://arxiv.org/abs/2611.26248","topics":["Evaluation"],"authors":["Yang Wan","Linchao Zhu"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.26248","announceDate":"2026-11-20","abstract":"AI agents are increasingly expected to act as AI scientists, which requires three increasingly open abilities: carrying out a given computational workflow correctly, choosing the next measurements from a given design space, and designing their own experiments. Existing benchmarks mainly evaluate the first two abilities, in a terminal or in a closed loop that selects from predefined candidates. Evaluating the third ability requires reliably executing an experiment that an agent designs, with readings grounded in a real laboratory. We introduce TwinLab-Bench, which evaluates AI scientists on self-designed experiments in 52 tasks from laboratories in the physical sciences, the life sciences, and engineering. The benchmark supports more than 100 experimental action types, and the agent's report is scored by comparison with a hidden answer taken from real laboratory records. Each task has its"},{"tags":["Evaluation"],"title":"DailySafe: Benchmarking Dynamic Safety Awareness in Everyday Multi-Turn Multimodal Interactions","pdf":"https://arxiv.org/pdf/2611.26298.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.26298","id":"arxiv:2611.26298","source":"hf","upvotes":4,"url":"https://arxiv.org/abs/2611.26298","topics":["Evaluation"],"authors":["Xuankun Rong","Xinhao Deng","Wenzhang Jiang","Ziheng Peng","Siyuan Liang","Wenke Huang","Pablo Arbelaez","Mang Ye"],"arxiv":"https://arxiv.org/abs/2611.26298","abstract":"As multimodal large language models (MLLMs) become increasingly integrated into everyday life, their ability to provide safe and reliable assistance in realistic daily activities remains insufficiently explored. Existing safety benchmarks primarily focus on isolated harmful requests or adversarial scenarios, overlooking the safety risks that may arise as ordinary tasks unfold. In practice, users pursue legitimate goals through multi-turn, multimodal interactions, where seemingly benign requests may become safety-critical when considered alongside earlier actions and visual observations. This calls for Dynamic Safety Awareness, the ability to track evolving task conditions, recognize implicit contextual risks, and provide safe and helpful assistance. To systematically evaluate this capability, we introduce DailySafe, a benchmark comprising 195 naturalistic multi-turn, multi-image interact"},{"tags":["LLM Training","Evaluation","Fine-tuning"],"title":"Suppressing the Shortcut Hidden Behind the Gains of VideoLLM Fine-Tuning","pdf":"https://arxiv.org/pdf/2611.25776.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.25776","id":"arxiv:2611.25776","source":"hf","upvotes":3,"url":"https://arxiv.org/abs/2611.25776","topics":["LLM Training","Evaluation","Fine-tuning"],"authors":["Youngwoo Shin","Jongsuk Kim","Junmo Kim"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.25776","announceDate":"2026-11-20","abstract":"Supervised fine-tuning (SFT) is the stage in which Video Large Language Models (VideoLLMs) advance their capability to reason over video. However, the VideoLLM also learns to answer from textual regularities of its training data, a shortcut that bypasses the video. The regularities behind the shortcut are hard to define at the data level, and the shortcut forms regardless of training epoch, data size, or backbone. The shortcut is hidden behind a rise in accuracy within the training distribution, yet it is not required for the rise and even costs SFT the gain the video offers under distribution shift. We therefore propose Video-Evidence Training via Orthogonal projection (VETO), which intervenes on the fine-tuning update where the shortcut is written rather than on the data. VETO calibrates the subspace that the text alone occupies in the activations of the base model and projects the upd"},{"tags":["Reflection"],"title":"PlayCraft: Designing Engaging Games from Agent Play Experience","pdf":"https://arxiv.org/pdf/2611.26624.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.26624","id":"arxiv:2611.26624","source":"hf","upvotes":2,"url":"https://arxiv.org/abs/2611.26624","topics":["Reflection"],"authors":["Weihao Cheng"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.26624","announceDate":"2026-11-20","abstract":"Recent AI agents can generate playable games, but these games are not necessarily engaging. Mastery is a key source of engagement, yet designing for it requires extensive human play and tuning. We propose PlayCraft, an automated framework that uses a vision-based agent to play games and draws on its detailed play experience to revise them for mastery. Starting from an initial game, PlayCraft alternates between playing and crafting. In the playing stage, a player agent watches the game screen, uses the controls, and pursues the game objective over repeated episodes while retaining memory. After each episode, it reports its progress, outcomes, decisions, and reflections. In the crafting stage, a crafter agent uses these reports to revise the game. It estimates player abilities, predicts performance at different proficiency levels, and compares those predictions with a target learning progr"},{"tags":["LLM Training","Evaluation"],"title":"TwinD: Generalizing Deepfake Detection from Blending to Entire Face Synthesis","pdf":"https://arxiv.org/pdf/2611.25935.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.25935","id":"arxiv:2611.25935","source":"hf","upvotes":1,"url":"https://arxiv.org/abs/2611.25935","topics":["LLM Training","Evaluation"],"authors":["Andrii Yermakov","Jan Cech","Mario Fritz","Jiri Matas"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.25935","announceDate":"2026-11-20","abstract":"Facial deepfake detectors are usually trained on blending fakes, where a generated face is pasted back into a real frame. Recent generators synthesize the entire face and leave no traces of blending. On a benchmark of 19 datasets released from 2019 to 2026, the best prior facial deepfake detector reaches a mean AUROC of 96.2% on ten blending datasets, but none exceeds 78.1% on five datasets of entire face synthesis (EFS). AI-generated content (AIGC) detectors do not close this gap. We propose TwinD, a detector trained on FaceForensics++ fakes and two kinds of twins: fakes made from a real frame. A reconstruction twin is a real frame reconstructed by an autoencoder, with the real pixels put back in a random region. It targets the neural traces of a decoder. A blob twin blends an altered copy of a real frame with the frame itself, targeting blending artifacts. It needs no generator and no "},{"tags":["Reasoning","Hallucination","Evaluation","Fine-tuning"],"title":"TuringSpace: Grounding Spatial Intelligence in Action with Interactive CAPTCHAs","pdf":"https://arxiv.org/pdf/2611.25387.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.25387","id":"arxiv:2611.25387","source":"arxiv","upvotes":23,"url":"https://arxiv.org/abs/2611.25387","topics":["Reasoning","Hallucination","Evaluation","Fine-tuning"],"authors":["Xuwei Ding","Skylar Zhai","Linxin Song","Jiarui Feng","Dongqi Fu","Huajun Xi","Junnan Li","Jingcheng Liang","Jieyu Zhao","Yinglong Xia","Hong Li","Jian Kang"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.25387","announceDate":"2026-11-20","abstract":"Humans act in the visual world by inferring the 3D layout behind a 2D view, predicting how an action changes it, and correcting themselves after seeing the result. Can multimodal large language models (MLLMs) do the same? CAPTCHAs offer a natural test, since humans solve them through this very loop, clicking and dragging on the screen and adjusting after each result. Yet existing CAPTCHA benchmarks are largely solved and rarely spatial, while spatial benchmarks rarely require action. We therefore present TuringSpace, a synthetic web environment of 125 interactive CAPTCHAs that span five spatial abilities and must be solved through clicks and drags on the screen. Every task is a program that generates new instances with a checker and an oracle, so the tasks also form a scalable training gym. Humans solve 94.1% of the tasks, whereas the best model, GPT-6 Astra, still fails 25.9% of them, a"},{"tags":["Post-Training","Fine-tuning"],"title":"RL Post-Training in Diffusion Transformers Is Activation Steering","pdf":"https://arxiv.org/pdf/2611.26627.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.26627","id":"arxiv:2611.26627","source":"arxiv","upvotes":16,"url":"https://arxiv.org/abs/2611.26627","topics":["Post-Training","Fine-tuning"],"authors":["Tuna Han Salih Meral","Kaan Oktay","Alec Helbling","Atakan Kara","Duen Horng Chau","Pinar Yanardag"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.26627","announceDate":"2026-11-20","abstract":"Reinforcement learning (RL) post-training substantially improves the visual quality, text rendering, and compositional accuracy of diffusion transformers. Because capabilities such as rendering requested text or composing multiple objects are inherently prompt-dependent, a natural hypothesis is that improving them requires learning complex, input-dependent transformations. To isolate how much of these gains an input-independent shift explains, we probe each RL-tuned model with a deliberately simple parameterization: a fixed set of steering vectors added to the block outputs of the frozen base model. On SD3.5-M, these vectors hold 65x fewer parameters than the RL-tuned LoRA (0.29M against 18.8M). We fit them to match the velocity predictions of public RL-tuned checkpoints, with no reward in the objective. Although the vectors are identical for every prompt, token, and sampling seed, they "},{"tags":["Evaluation","Data Engine"],"title":"Phantom Success, Silent Failure: Auditing the Success Checkers of Simulated Manipulation Benchmarks","pdf":"https://arxiv.org/pdf/2611.25179.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.25179","id":"arxiv:2611.25179","source":"arxiv","upvotes":4,"url":"https://arxiv.org/abs/2611.25179","topics":["Evaluation","Data Engine"],"authors":["Zirui Song","Jiadong Zhang","Zheng Lu","Xiaosong Ma","Xiaojun Chang","Xiuying Chen"],"submittedDate":"2026-11-18","arxiv":"https://arxiv.org/abs/2611.25179","announceDate":"2026-11-20","abstract":"Simulated manipulation benchmarks measure policy performance using hand-written success checkers that label each episode as a success or failure. Passing an expert demonstration shows that a checker accepts one way of completing the task. Learned policies, however, may stop after partial progress or complete the task in a different way. A checker may then accept an incomplete execution (phantom success) or reject an execution that satisfies the instruction (silent failure). In this paper, we introduce SimAudit, an LLM-based pipeline that audits success checkers against task instructions. SimAudit analyzes the instruction and checker code to identify scenarios where the two may disagree, recreates those scenarios in simulation, and runs the original checker. Multi-view renderings are then used to verify whether the observed behavior satisfies the instruction. Across RoboTwin 2.0, RoboCasa"},{"tags":["Fine-tuning"],"title":"A CPU Inside an LLM: Zero-Gradient Compilation of Exact Circuits into Pretrained Weights","pdf":"https://arxiv.org/pdf/2611.26450.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.26450","id":"arxiv:2611.26450","source":"arxiv","upvotes":4,"url":"https://arxiv.org/abs/2611.26450","topics":["Fine-tuning"],"authors":["Tanmay Sah"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.26450","announceDate":"2026-11-20","abstract":"Pretrained language models (LMs) remain unreliable on exact multi-digit arithmetic without gradient fine-tuning or external tool interpreters. We introduce closed-form, zero-gradient circuit-grafting primitives that compile deterministic computation directly into pretrained LM weights using zero training examples and zero runtime hooks, while bounding per-layer normalization drift and preserving natural-language (NL) competence. Our construction combines three analytical mechanisms: (1) two-layer Mellin-GLU quadrature over bias-free SwiGLU/GeGLU layers, turning unknown per-token RMSNorm scaling into translation along a log-spaced gate grid ($>250\\times$ dynamic range) with IEEE 754 error bounds; (2) cross-token scale cancellation via signed Chebyshev Indefinite-RoPE self-sink attention and memoryless SiLU-antisymmetric GatedDeltaNet shifts; and (3) axis-aligned width extension ($d \\to d+"},{"tags":["Alignment"],"title":"Direct3D-V3: Latent-Free Diffusion Transformers in the Native Voxel Domain","pdf":"https://arxiv.org/pdf/2611.26511.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.26511","id":"arxiv:2611.26511","source":"arxiv","upvotes":4,"url":"https://arxiv.org/abs/2611.26511","topics":["Alignment"],"authors":["Shuang Wu","Jiachen Qian","Youtian Lin","Feihu Zhang","Philip Torr","Yao Yao","Xun Cao"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.26511","announceDate":"2026-11-20","abstract":"Native 3D generation has largely been built around latent diffusion, with recent advances concentrating on stronger variational autoencoders (VAE) and increasingly elaborate latent representations, from vecset and triplanes to structured sparse voxels. Despite their architectural differences, these methods all share the same premise: geometry is first compressed into a latent space and only then modeled by the generator. We take a different route and propose Direct3D-V3, a latent-free diffusion transformer (DiT) framework that discards the VAE altogether and operates in the native voxel domain, directly modeling raw SDF voxel grids during both training and sampling. To make this direct voxel formulation geometrically reliable, we introduce an implicit manifold regularization over neighboring voxels to suppress non-watertight surfaces, and convert predicted SDF grids into meshes via March"},{"tags":["Evaluation","Agent Framework"],"title":"Inhabitant: An Agent Framework for Long-Horizon Human-Scene Interaction with Spatial Control and Quantitative Feedback","pdf":"https://arxiv.org/pdf/2611.25005.pdf","date":"2026-11-20","hfUrl":"https://huggingface.co/papers/2611.25005","id":"arxiv:2611.25005","source":"arxiv","upvotes":2,"url":"https://arxiv.org/abs/2611.25005","topics":["Evaluation","Agent Framework"],"authors":["Yao Zhang","Zhuchenyang Liu","Yu Xiao"],"submittedDate":"2026-11-18","arxiv":"https://arxiv.org/abs/2611.25005","announceDate":"2026-11-20","abstract":"Recent work on human-scene interaction (HSI) generation moves from single interactions to long-horizon interaction, where a language-model agent plans and executes a sequence of interactions in a 3D scene under one instruction. However, existing agents struggle in challenging everyday scenarios (e.g., picking up a toy and throwing it into a basket) because they lack spatial control over the motion and quantitative feedback on its execution, and they often fail to complete the interaction sequence. To address these gaps, we present Inhabitant, a training-free agent framework in which the agent specifies each motion through positions, paths and poses, measures how the executed interaction deviates from its intent, and revises the control specification accordingly. For an extensive evaluation in such scenarios, we build Inhabit, a benchmark of 75 household tasks in 31 furniture layouts of a"},{"tags":["Agent Safety","Post-Training","LLM Training","Multi-Agent","Reasoning"],"title":"Verifiable Logic in Medical LLMs: A Critical Review of Agentic Clinical Reasoning Optimization and Neuro-Symbolic Grounding","pdf":"https://arxiv.org/pdf/2611.25898.pdf","date":"2026-11-20","id":"arxiv:2611.25898","source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2611.25898","topics":["Agent Safety","Post-Training","LLM Training","Multi-Agent","Reasoning","Hallucination","Evaluation"],"authors":["Youssef ElNahas","Adel Ammar","Soumaya Chaffar","Wadii Boulila"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.25898","announceDate":"2026-11-20","abstract":"Clinical large language models are usually judged by whether the final answer is right. Yet a model can reach a fluent, plausible output through invalid reasoning that static benchmarks do not detect, and confident hallucination, causally invalid inference, and spurious demographic shortcuts can pass conventional evaluation. This critical review covers four paradigms in turn: how clinical hallucination arises and why static metrics miss it; the agentic hallucination cascade, in which multi-agent and tool-augmented systems propagate and amplify early reasoning errors; process reward modeling as step-level supervision; and neuro-symbolic grounding, in which formal logic engines, ontology reasoners, and knowledge graphs place verifiable constraints on neural output. Within their encoded domains, systems with symbolic veto layers offer guarantees that hold relative to their encoded knowledge"},{"tags":["LLM Training","VLM Training","Tool Use","Reasoning","Hallucination"],"title":"Learning to Think with Images Faithfully via Adaptive Data Selection","pdf":"https://arxiv.org/pdf/2611.26199.pdf","date":"2026-11-20","id":"arxiv:2611.26199","source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2611.26199","topics":["LLM Training","VLM Training","Tool Use","Reasoning","Hallucination","Evaluation","Data Engine"],"authors":["Yu Zhao","Jiaxin Zhang","Rohit Saxena","Fazl Barez","Pasquale Minervini","Yiwen Guo"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.26199","announceDate":"2026-11-20","abstract":"Thinking with images (TwI) empowers vision-language models (VLMs) to overcome perceptual bottlenecks by actively cropping and zooming into fine-grained visual details, promising both higher accuracy and interpretable, region-grounded reasoning. However, our analysis shows that the improved accuracy of TwI models does not guarantee faithful tool use; they frequently invoke tools without actually relying on the zoomed region, undermining the reliability of tool-assisted reasoning. We trace this unfaithful behaviour to the training data: when questions are answerable without zooming, the model can answer correctly while ignoring the returned evidence, and this problem is exacerbated during training as the model becomes better at answering without tools. To keep zooming useful throughout training, we adapt the training data to the model's evolving capability and train on questions where corr"},{"tags":["LLM Training","Reasoning","Planning","Code Agent","Fine-tuning"],"title":"Beyond Weight Updates: Evolving Agent Harnesses for Domain Specialization","pdf":"https://arxiv.org/pdf/2611.25380.pdf","date":"2026-11-20","id":"arxiv:2611.25380","source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2611.25380","topics":["LLM Training","Reasoning","Planning","Code Agent","Fine-tuning","RL for LLM"],"authors":["BoHao Chen"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.25380","announceDate":"2026-11-20","abstract":"Domain specialization of LLM agents is usually framed as a weight-update problem: collect trajectories, run reinforcement learning (RL) or supervised fine-tuning (SFT), and deploy a new checkpoint. We study a complementary axis: evolving the \\textbf{agent harness}---the system prompt, tool schemas, skill library, and planning scaffolding---while keeping the policy frozen. We cast harness evolution as an RL-style outer loop and instantiate it with GEPA, a reflective evolutionary optimizer. The resulting harness adapters require no GPU training, are loadable per vertical domain, and compose with weight-based RL. Experiments with Codev, a Claude Code-style coding agent, on SWE-bench Verified, OfficeBench, and Terminal-Bench show a consistent pattern: weight updates give the strongest single-path gains, harness evolution recovers most of those gains at a small fraction of the compute, and co"},{"tags":["Multi-Agent","Reasoning","Planning","Evaluation","Reflection"],"title":"LM-based Personalized Travel Planner","pdf":"https://arxiv.org/pdf/2611.25531.pdf","date":"2026-11-20","id":"arxiv:2611.25531","source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2611.25531","topics":["Multi-Agent","Reasoning","Planning","Evaluation","Reflection","Agent Framework"],"authors":["Amandi Nimasha","Oshadha Wijerathne","Dushan Fernando","Nisansa de Silva","Srinath Perera"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.25531","announceDate":"2026-11-20","abstract":"Effective travel planning requires handling multiple information sources, managing constraints, and tailoring recommendations to user preferences. While LLMs have introduced dynamic, context-aware decision-making, single-agent models often struggle with complex multi-step reasoning, constraint adherence, and modular execution. To overcome these limitations, we propose a hierarchical multi-agent framework where a supervising chatbot agent coordinates specialized agents for schedule validation, user query formulation, real-time data retrieval, and constraint-aware itinerary generation. By integrating LLM reasoning, external APIs, and iterative refinement mechanisms based on a deterministic, multi-dimensional scoring framework, our approach ensures adaptability, efficiency, and personalization. Evaluations on the well-known TravelPlanner benchmark demonstrate improvements in Budget Constrai"},{"tags":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"title":"ROAM-GRPO: Enforcing Reasoning Diversity in GRPO via Routed Off-mode Approach Mining","pdf":"https://arxiv.org/pdf/2611.25926.pdf","date":"2026-11-20","id":"arxiv:2611.25926","source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2611.25926","topics":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"authors":["Jeff Duan","Matt Thomson"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.25926","announceDate":"2026-11-20","abstract":"Supervised fine-tuning (SFT) paired with Reinforcement Learning with Verifiable Rewards (RLVR) has become the dominant recipe for post-training LLMs on complex reasoning tasks, but has been shown to collapse the policy into a low-diversity mode. Repeated LLM outputs are nearly identical, and pass@k accuracy converges or degrades as a result. We propose ROAM-GRPO (Routed Off-mode Approach Mining for GRPO), an augmentation to the GRPO algorithm which incentivizes exploration of distinct reasoning strategies and aims to increase output creativity during evaluation. ROAM-GRPO detects well-solved problems during training and transfers them to an \"off-mode\" track. The model is prompted to produce distinct solution strategies to such problems, which are verified for logical validity and distinctness by an LLM judge and subsequently self-distilled into the policy. Training Qwen3.5-2b on a 1,000-"},{"tags":["Agent Safety","Error Attribution","Multi-Agent","Code Agent","Evaluation"],"title":"Replication of Agentic Security Events: Audit and Investigation (ROGUE-AI)","pdf":"https://arxiv.org/pdf/2611.26553.pdf","date":"2026-11-20","id":"arxiv:2611.26553","source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2611.26553","topics":["Agent Safety","Error Attribution","Multi-Agent","Code Agent","Evaluation","Agent Framework"],"authors":["Mengxiao Wang","Mahbub Alam","Kalyan Nakka","Nitesh Saxena"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.26553","announceDate":"2026-11-20","abstract":"Agents based on large language models (LLMs) can now delete files and send payments on behalf of their users. News media reports routinely describe failures of these agents (e.g., Replit's coding agent deleting a production database), but a report often only says what went wrong and rarely (in)validates the incident or finds its root cause. Incident catalogs collect these reports, and benchmarks record whether agents fail, but neither replicates an incident nor tests the cause its report might identify. In this paper, we present ROGUE-AI (Replication of Agentic Security Events: Audit and Investigation), a multi-agent framework that closes the above gap and rebuilds each reported incident offline together with a matched control that lacks only the blamed cause, and runs agents on both. Our results suggest that ROGUE-AI is able to reproduce the reported harm in 89% of its 108 attempted rep"},{"tags":["Post-Training","LLM Training","VLM Training","Reasoning","Evaluation"],"title":"EgoWitness: Benchmarking Instance-Level Spatial Memory and Reasoning in Egocentric Video Streams","pdf":"https://arxiv.org/pdf/2611.25849.pdf","date":"2026-11-20","id":"arxiv:2611.25849","source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2611.25849","topics":["Post-Training","LLM Training","VLM Training","Reasoning","Evaluation","Fine-tuning"],"authors":["Zhengru Fang","Zehao Liu","Mingyu Tsoi","Yaoyu Zhu","Junlong Li","Fengmao Lv","Sijie Cheng","Yuanliang Sun","Fang Yang","Jun Zhang"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.25849","announceDate":"2026-11-20","abstract":"Recalling where and when an object was last seen and who saw it requires recognizing it across days and people. Existing long-video benchmarks focus on events, object categories, or relative locations, leaving instance-level spatial memory largely untested in multimodal models. To address this gap, we present EgoWitness, a benchmark for instance-level spatial memory and reasoning in egocentric video. Its 8,453 human-verified questions span approximately 324 hours of week-long and short-horizon recordings and test seven abilities, from recognizing an object or room to recalling who saw it and reasoning about room visits. Over one million reviewed masks of 34 registered landmarks and 21 movable-object labels are linked through room timelines. Among twelve direct vision-language models (VLMs), open-weight models reach at most 46.97% accuracy, and none exceeds 35% on identifying who saw an o"},{"tags":["LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"title":"Training LLMs to Follow Reasoning Instructions with Minimal Edits","pdf":"https://arxiv.org/pdf/2611.26342.pdf","date":"2026-11-20","id":"arxiv:2611.26342","source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2611.26342","topics":["LLM Training","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"authors":["Alexandra Yakovleva","Luat Gia Khoi Nguyen","Juho Kannala","Harri Valpola","Alexander Ilin"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.26342","announceDate":"2026-11-20","abstract":"Large language models increasingly rely on extended reasoning traces, yet the training signals used to shape this behavior remain coarse. Supervised fine-tuning on full trajectories forces the model to imitate an entire demonstration, overconstraining its output distribution, while trajectory-level reinforcement learning provides only weak credit assignment, rewarding or penalizing whole completions without identifying where they succeed or fail. We propose edit-based training, a general framework for learning from a model's own trajectories via localized textual corrections. Given a sampled completion, an editor identifies the first point of failure under a specified criterion and proposes a minimal replacement span. The model is then supervised only on these edited spans. By design, this concentrates supervision where the model's reasoning first breaks down and aims to preserve its exi"},{"tags":["VLM Training","Reasoning","Planning","Evaluation","Multimodal Agent"],"title":"Generalist Meets Specialists: An Evolving Multimodal Agent with Persistent Tool Orchestration for Traffic Scenario Understanding","pdf":"https://arxiv.org/pdf/2611.25868.pdf","date":"2026-11-20","id":"arxiv:2611.25868","source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2611.25868","topics":["VLM Training","Reasoning","Planning","Evaluation","Multimodal Agent"],"authors":["Linjia Kang","Binhan Jiang","Juan Yang","Zhiqin Song","Xiangsen Wu","Qionglin Ren","Jiang Liu","Zhongjiang He","Hao Sun"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.25868","announceDate":"2026-11-20","abstract":"Traffic scenario understanding requires combining fine-grained visual evidence with spatial and temporal reasoning. Tool-augmented vision-language models (VLMs) can use specialized perception tools, but effective collaboration faces two challenges: terminal rewards provide limited guidance for intermediate decisions and error recovery, while repeated planning adds unnecessary cost across similar tasks. Echoing the fast-slow dichotomy of human cognition, we propose StarTV-Agent, which combines policy learning with experience evolution to support adaptive reasoning when needed and efficient reuse of prior experience when possible. During training, Role-Sensitive Process Optimization (RSPO) combines process advantages with terminal advantages, while Weakness-Driven Demonstration Learning (WDL) provides validated teacher demonstrations targeting the student's weak questions. During inference"},{"tags":["Post-Training","LLM Training","Planning","Evaluation","RL for LLM"],"title":"Decision-Focused Reinforcement Learning for LLM Post-Training","pdf":"https://arxiv.org/pdf/2611.25597.pdf","date":"2026-11-20","id":"arxiv:2611.25597","source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2611.25597","topics":["Post-Training","LLM Training","Planning","Evaluation","RL for LLM"],"authors":["Haotian Zhai","Leqi Liu"],"submittedDate":"2026-11-19","arxiv":"https://arxiv.org/abs/2611.25597","announceDate":"2026-11-20","abstract":"Large language models (LLMs) have shown promise as predictors across various tasks, benefiting from their ability to use information from unstructured context. However, when predictions serve as parameters of downstream optimization problems, higher prediction accuracy does not necessarily translate into lower decision costs. We propose decision-focused reinforcement learning (DFRL), a framework for post-training LLMs to predict optimization parameters using negative downstream decision regret as reward. DFRL trains LLM predictors to minimize the costs of the decisions induced by their predictions, without requiring downstream convexity or differentiability, and integrates readily into existing RL post-training frameworks. To address expensive reward evaluation, we develop two approaches. Heuristic warm-starting uses inexpensive approximate rewards during an initial phase before switchin"},{"tags":["Agentic Search","Multi-Agent","Tool Use","Evaluation"],"title":"FinVeriQA: Financial Research Agents for Question Answering: Routing, Retrieval, MCP Tool Use, and Provenance-Aware Evidence Verification","pdf":"https://arxiv.org/pdf/2611.25071.pdf","date":"2026-11-20","id":"arxiv:2611.25071","source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2611.25071","topics":["Agentic Search","Multi-Agent","Tool Use","Evaluation"],"authors":["Meenakshi Rajpurohit","Anna Phan","Ravikumar Komandur Narayanan","Gunanidhi Ramakrishnan","Nathan Howland"],"submittedDate":"2026-11-18","arxiv":"https://arxiv.org/abs/2611.25071","announceDate":"2026-11-20","abstract":"Large language models (LLMs) write fluent financial analyses but miscompute ratios, recall stale prices, and route questions to the wrong tool with high confidence. We ask which component should do each job in a financial question-answering assistant, and study it with FinVeriQA, an open-source multi-agent research prototype over SEC filings and live market data: a compact typed-decision model (Laya) routes each question and screens out advice requests, Python computes every number, retrieval and tools fetch evidence, Mistral-7B writes a cited answer, a code validator checks that cited IDs exist and that numbers match computed notes, and a Model Context Protocol (MCP) server exposes the pipeline. In live experiments, Laya routed better than Mistral-7B (0.85 vs. 0.52; overall 0.86 vs. 0.68, McNemar p = 0.0003); a 12B Mistral decided no better, and DeepSeek-R1-8B decided better (0.79 vs. 0"},{"tags":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"title":"LSP-RAG: Latent Scoring Perspectives for Knowledge Graph Retrieval-Augmented Generation","pdf":"https://arxiv.org/pdf/2611.25229.pdf","date":"2026-11-20","id":"arxiv:2611.25229","source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2611.25229","topics":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"authors":["Haochen Liu","Guanghui Min","Song Wang","Yada Zhu","Chen Chen","Jundong Li"],"submittedDate":"2026-11-18","arxiv":"https://arxiv.org/abs/2611.25229","announceDate":"2026-11-20","abstract":"Large Language Models (LLMs) have demonstrated strong capabilities in open-domain question answering, but often struggle with factual accuracy and multi-hop reasoning due to the incompleteness of the training corpora. A promising solution is Knowledge Graph Retrieval-Augmented Generation (KG-RAG), which supplements LLMs with structured knowledge retrieved from external knowledge graphs (KGs). However, existing KG-RAG methods either rely on large-scale language models (e.g., ChatGPT) to guide the retrieval process, which leads to high computational costs, or suffer from limited retrieval quality when using lightweight language models, particularly under multi-hop scenarios. We propose LSP-RAG (Latent Scoring Perspectives for Retrieval-Augmented Generation over Knowledge Graphs), a novel KG-RAG framework that enhances hop-wise KG knowledge retrieval through multi-perspective prompted scori"},{"tags":["Agentic RAG","Agentic Search","Planning","Evaluation"],"title":"From Industrial Product Documentation to Automated Digital Product Passport Generation: An Experimental Study of Large Language Models","pdf":"https://arxiv.org/pdf/2611.24998.pdf","date":"2026-11-20","id":"arxiv:2611.24998","source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2611.24998","topics":["Agentic RAG","Agentic Search","Planning","Evaluation"],"authors":["Marco Buecheler","Grant Richards","Nathan Hartman"],"submittedDate":"2026-11-18","arxiv":"https://arxiv.org/abs/2611.24998","announceDate":"2026-11-20","abstract":"Manufacturing companies that are planning to sell certain products in the European Union (EU) will be required to provide mandatory digital product passports (DPPs). The use of DPPs is to provide standardized product information throughout multiple product life cycles in a circular economy. Required passport information, such as technical specifications, material composition, and environmental product footprint, is available in manufacturers' data sources but is scattered across different heterogeneous systems, documents, and data formats. The given paper investigates using large language models (LLMs) to automate the generation of DPPs based on the asset administration shell (AAS). A retrieval-augmented generation (RAG) approach is used to extract product information from industrial documentation and generate populated AAS instances. Product documentation is processed and divided into t"},{"tags":["Agentic RAG","Agentic Search","Hallucination","Evaluation"],"title":"A Neurosymbolic Multimodal Framework for 30-Day Diabetic Readmission Prediction: Integrating Structured EHR Data, Dense Clinical Embeddings, and Knowledge-Grounded Symbolic Extraction","pdf":"https://arxiv.org/pdf/2611.25236.pdf","date":"2026-11-20","id":"arxiv:2611.25236","source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2611.25236","topics":["Agentic RAG","Agentic Search","Hallucination","Evaluation"],"authors":["Una Suman Kumar Patro","Sibangi Subhadarsani","Narendra Badam"],"submittedDate":"2026-11-18","arxiv":"https://arxiv.org/abs/2611.25236","announceDate":"2026-11-20","abstract":"Unplanned 30-day readmissions among patients with diabetes mellitus impose a substantial clinical and economic burden, yet most predictive models use only structured electronic health record (EHR) data and ignore free-text clinical notes, which often contain code-mixed Hindi-English (Hinglish) phrasing and negation that general-purpose language models parse unreliably. We propose a neurosymbolic multimodal framework evaluated on the public Diabetes 130-US Hospitals dataset (101,766 encounters; 71,518 patients) with a patient-level grouped 80/20 split. Three streams are fused: engineered structured features; 32 components of Bio_ClinicalBERT note embeddings obtained by truncated singular value decomposition; and symbolic entities extracted by an open-weight clinical language model within a three-stage hybrid retrieval-augmented generation pipeline (dense retrieval, sparse lexical retrieva"},{"tags":["VLM Training","Reasoning","Planning","RL for LLM"],"title":"Bridging vision-language reasoning and learned control for legged navigation in the wild","pdf":"https://arxiv.org/pdf/2611.25215.pdf","date":"2026-11-20","id":"arxiv:2611.25215","source":"arxiv","upvotes":0,"url":"https://arxiv.org/abs/2611.25215","topics":["VLM Training","Reasoning","Planning","RL for LLM"],"authors":["Takahiro Miki","Robin Schmid","Manthan Patel","Turcan Tuna","Julia Richter","Julian Nubert","Joonho Lee","Matthias Müller","Marco Hutter"],"submittedDate":"2026-11-18","arxiv":"https://arxiv.org/abs/2611.25215","announceDate":"2026-11-20","abstract":"Autonomous navigation in diverse real-world environments remains one of the greatest challenges in robotics. It demands both robust low-level motion control to handle diverse terrain and high-level reasoning to interpret environmental cues. We present ROAM (Robust Open-world Autonomous Mobility), a system that enables legged robots to perform kilometer-scale navigation in complex alpine and urban settings. ROAM combines the world knowledge of a Vision-Language Model (VLM), pre-trained on internet-scale data, with robust locomotion and local planning policies learned in simulation via reinforcement learning (RL). The VLM provides common-sense reasoning and semantic interpretation of the scene, assessing risks, interpreting signs, and producing semantic labels with associated navigation costs. An open-vocabulary segmentation module converts these labels into a dense, real-time risk map, wh"}],"archive":[],"latestPath":"data/latest.json"};
